) VALUES (
    #{originalInvoiceId}, #{correctionReason}, #{issueDate}, #{taxableSupplyDate},
    #{status, typeHandler=cz.palo.autoservis.config.mybatis.PgEnumTypeHandler$InvoiceStatusHandler},
    #{createdBy}
)

mapper.select:
SELECT 
FROM billing.credit_notes AS cn
WHERE cn.id = #{id}

mapper.update:
UPDATE billing.credit_notes
SET status = #{status, typeHandler=cz.palo.autoservis.config.mybatis.PgEnumTypeHandler$InvoiceStatusHandler}
WHERE id = #{id}
  AND status = #{expectedStatus, typeHandler=cz.palo.autoservis.config.mybatis.PgEnumTypeHandler$InvoiceStatusHandler}

mapper.delete:
DELETE FROM billing.credit_notes
WHERE id = #{id}
  AND status = 'DRAFT'::billing.invoice_status
